import{z as n,x as s,o as e,c as p,q as o,j as A,D as i,d as E,s as B,S as r,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"rail-optimized 拓扑","description":"","frontmatter":{"title":"rail-optimized 拓扑","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rail-optimized-topology.md","filePath":"llm/rail-optimized-topology.md","lastUpdated":1791413859000}'),d={name:"llm/rail-optimized-topology.md"};function P(D,l,m,C,u,c){const t=s("Mermaid");return e(),p("div",null,[l[2]||(l[2]=o('<h1 id="rail-optimized-拓扑" tabindex="-1">rail-optimized 拓扑 <a class="header-anchor" href="#rail-optimized-拓扑" aria-label="Permalink to &quot;rail-optimized 拓扑&quot;">​</a></h1><div class="epigraph"><p>轨优化把「第 $i$ 张 GPU」对齐到同一条上行。数据并行的 All-Reduce 喜欢这种对齐；专家并行的 All-to-All 不一定买账。</p><footer>—— NVIDIA DGX SuperPOD 一类参考架构中的 rail-optimized 脂肪树；对照 Clos 分层</footer></div><p><a href="/llm/collective-bandwidth-model">上一课</a> 把 \\(\\beta\\) 当成链路常数。本课给常数一个拓扑：GPU 集群常见的 <strong>rail-optimized</strong> 脂肪树——每个节点第 \\(i\\) 张 GPU 接到第 \\(i\\) 条轨（一组叶子–脊柱），希望同号 GPU 之间的集合通信不打到别的轨上。缺口是：这种设计为哪一种集体流量优化，以及它与 <a href="/llm/all-to-all-vs-clos">全互连 vs Clos</a> 里柜外 Clos 如何咬合。<a href="/llm/nvlink">NVLink</a> 域仍是节点内或超节点内；轨是 Scale-Out 层的画法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>普通 Clos 上，网卡哈希可能把同一 DP 组的流量打散到多条上行，再在脊柱汇聚时极化。GPU 训练的集体流量高度同步：所有 rank 几乎同时发出同样大小的块，哈希极化会让一条轨过载、其余空转，step 被最慢轨绑住。轨优化的假设是：把拓扑做成「平面 \\(i\\) 只承载 GPU \\(i\\)」，再让并行网格把 DP 组画在同号 GPU 上，于是 All-Reduce 的跨节点段走一条干净的平面，不必与 TP 的节点内流量争同一条上行。</p><p><span class="marginnote">哈希极化像高速口的随机分流：本想让车流均摊到 8 条车道，算法却常把同一支车队全怼进同一条——一条道堵死、其余空跑。集体通信是全队同时出发、互相等待，最慢的那条轨决定整体时间，所以堵一条等于堵全部。</span></p><p>问题立刻变成两问：进程绑定是否真的让 rank 落在设计的轨上；流量模式是否真是「同号到同号」。后者对 DP 梯度同步大致成立，对 EP All-to-All 不成立——置换是任意到任意，轨对齐帮不上，还可能把本可打散的流量关进 \\(N_{\\mathrm{gpu\\_per\\_node}}\\) 张彼此隔离的平面里，平面内部更挤。</p><p><span class="marginnote">「Rail」在这里不是铁路隐喻作文，而是编号对齐：rail 0 连接各节点的 GPU 0。文献与厂商参考架构都这么用。不要和存储的 rail 或电源轨混谈，除非设施文档明确同一根铜排。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规划分三步。第一，物理：每张 GPU 尽量对应一张（或一组）NIC 端口，PCIe 亲和在同一交换机下，GPU Direct RDMA 走得通。第二，逻辑：NCCL 拓扑与 <code>CUDA_VISIBLE_DEVICES</code>、进程绑定保证 rank 的 GPU 号与 NIC 号一致。第三，并行网格：DP 维沿「同轨」展开，TP / CP 维留在 <a href="/llm/nvlink">NVLink</a> 域内，不跨轨。</p><p>超节点（NVL72 一类）把第一层轨的半径扩大：域内不再需要轨，柜间 Clos 仍要轨优化。不要把柜内 Switch 当成若干 rail——软件看见的是平坦域。柜间若不用轨优化，72 卡域的对外 All-Reduce 会在叶子层变成随机哈希，超节点买到的 Scale-Up 优势到柜边被吐掉。</p>',11)),(e(),A(r,null,{default:i(()=>[B(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20G0%5B%22%E5%90%84%E8%8A%82%E7%82%B9%20GPU%200%22%5D%20--%3E%20R0%5B%22Rail%200%22%5D%0A%20%20G1%5B%22%E5%90%84%E8%8A%82%E7%82%B9%20GPU%201%22%5D%20--%3E%20R1%5B%22Rail%201%22%5D%0A%20%20DP%5B%22DP%20All-Reduce%22%5D%20--%3E%20R0%0A%20%20DP%20--%3E%20R1%0A%20%20TP%5B%22TP%20%2F%20%E5%9F%9F%E5%86%85%22%5D%20--%3E%20NVL%5B%22NVLink%20%E5%9F%9F%22%5D%0A%20%20EP%5B%22%E8%B7%A8%E8%8A%82%E7%82%B9%20EP%20All-to-All%22%5D%20--%3E%20MIX%5B%22%E6%89%93%E6%95%A3%E5%88%B0%E5%A4%9A%E8%BD%A8%20%2F%20%E6%8B%A5%E5%A1%9E%22%5D%0A"})]),fallback:i(()=>[...l[0]||(l[0]=[E(" Loading... ",-1)])]),_:1})),l[3]||(l[3]=a("p",null,[E("验收："),a("code",null,"nvidia-smi topo"),E(" 与网卡亲和；"),a("code",null,"nccl-tests"),E(" 在「只含同号 GPU」的进程组上 busbw 应接近该轨规格；把进程故意错绑后 busbw 应掉档。没有这组对照，不能声称集群是轨优化的——只能声称图纸是。")],-1)),l[4]||(l[4]=a("p",null,[a("span",{class:"marginnote"},"数字实例：「掉档」怎么读数——设每条轨规格 400 Gbps，同号 GPU 组实测 busbw 若只有 200 Gbps 上下，说明流量被打散或绑错了卡；而故意错绑后掉档越明显，越能证明平时的高带宽真来自轨对齐，不是碰巧。")],-1)),l[5]||(l[5]=a("h2",{id:"机制",tabindex:"-1"},[E("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),l[6]||(l[6]=a("p",null,"同步集体在 Clos 上的经典失败是 incast：多对一在某一跳汇聚。轨优化把 DP All-Reduce 的汇聚限制在平面内，平面的订阅比按全集群哈希更可预期。它不消除 \\(\\alpha\\)，只让 \\(\\beta\\) 更接近空载模型。自适应路由可以在平面内绕开热点，但若把流量绕到别的轨，就破坏了「GPU \\(i\\) 只走 rail \\(i\\)」的隔离，可能帮了 All-to-All、害了 DP。策略要按流量类型，不能全局开一种。",-1)),(e(),A(r,null,{default:i(()=>[B(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOT%5B%22%E4%B8%80%E6%9D%A1%E8%BD%A8%E5%87%BA%E7%8E%B0%E7%83%AD%E7%82%B9%EF%BC%8C%E5%A4%9A%E5%AF%B9%E4%B8%80%E6%B1%87%E8%81%9A%22%5D%20--%3E%20Q%7B%22%E8%87%AA%E9%80%82%E5%BA%94%E8%B7%AF%E7%94%B1%E7%BB%95%E4%B8%8D%E7%BB%95%E5%88%B0%E5%88%AB%E7%9A%84%E8%BD%A8%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E7%95%99%E5%9C%A8%E6%9C%AC%E8%BD%A8%E5%86%85%E6%8D%A2%E8%B7%AF%E5%BE%84%22%7C%20SAFE%5B%22%E9%9A%94%E7%A6%BB%E4%BF%9D%E6%8C%81%EF%BC%8CDP%20%E7%9A%84%20beta%20%E4%BB%8D%E5%8F%AF%E9%A2%84%E6%9C%9F%22%5D%0A%20%20Q%20--%3E%7C%22%E7%BB%95%E8%A1%8C%E5%88%B0%E5%85%B6%E4%BB%96%E8%BD%A8%22%7C%20MIX%5B%22GPU%20i%20%E5%8F%AA%E8%B5%B0%20rail%20i%20%E7%9A%84%E9%9A%94%E7%A6%BB%E8%A2%AB%E6%89%93%E7%A0%B4%22%5D%0A%20%20MIX%20--%3E%20A%5B%22EP%20All-to-All%20%E5%8F%AF%E8%83%BD%E5%8F%97%E7%9B%8A%22%5D%0A%20%20MIX%20--%3E%20B%5B%22DP%20%E6%B5%81%E9%87%8F%E6%B7%B7%E5%85%A5%E5%88%AB%E7%9A%84%E5%B9%B3%E9%9D%A2%EF%BC%8C%E5%8F%98%E6%85%A2%22%5D%0A%20%20A%20--%3E%20P%7B%22%E7%AD%96%E7%95%A5%E5%85%A8%E5%B1%80%E4%B8%80%E5%88%80%E5%88%87%EF%BC%9F%22%7D%0A%20%20B%20--%3E%20P%0A%20%20P%20--%3E%7C%22%E6%98%AF%22%7C%20BAD%5B%22%E4%B8%80%E7%B1%BB%E6%B5%81%E9%87%8F%E6%80%BB%E5%9C%A8%E5%90%83%E4%BA%8F%22%5D%0A%20%20P%20--%3E%7C%22%E5%90%A6%EF%BC%8C%E6%8C%89%E6%B5%81%E9%87%8F%E7%B1%BB%E5%9E%8B%E8%AE%BE%E7%AD%96%E7%95%A5%22%7C%20GOOD%5B%22DP%20%E4%BF%9D%E9%9A%94%E7%A6%BB%EF%BC%8CEP%20%E5%85%81%E8%AE%B8%E6%89%93%E6%95%A3%22%5D%0A"})]),fallback:i(()=>[...l[1]||(l[1]=[E(" Loading... ",-1)])]),_:1})),l[7]||(l[7]=o('<p><span class="marginnote">这张图回答「热点出现时自适应路由的两难」。它不像表面那样「只能更好」：绕行对 All-to-All 是解堵，对 DP 却是污染——两套流量的最优策略相反，所以结论是分流量配置，而不是找一个全局开关。</span></p><p>多租户时，两个作业的 DP 组若共享同一轨，隔离被打破。调度需要把作业的 GPU 号与轨当成资源的一部分，而不是只分配「8 张卡」。后课公平调度会回到 gang 与拓扑感知；本课只要求轨是调度输入。</p><p><span class="marginnote">以太网 RoCE 与 InfiniBand 都能做轨优化脂肪树。差别在拥塞控制（后课），不在「可不可以编号对齐」。把厂商名词当成拓扑发明是错的；对齐是布线与编号纪律。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要为了轨优化把 TP 组拆到多节点同号 GPU 上——同号 GPU 之间是网卡 \\(\\beta\\)，不是 NVLink。不要假设 All-to-All 自动受益。不要在超分严重的 Clos 上只靠轨优化：平面内部仍然可以过订阅。Dragonfly 等非 Clos 拓扑用另一套局部性，下一课对照，不要把 rail 概念硬套过去。</p><p>检查点与存储流量若走同一套 NIC，会周期性污染轨的 \\(\\beta\\)。存储平面分离是运维选项；做不到至少错开检查点与梯度同步的峰值。</p><p><span class="marginnote">为什么重要：检查点每隔一段时间要往存储写几十 GB 的模型参数，若与梯度同步共用网卡，轨的实测带宽就会周期性塌坑——你会误判成拓扑设计有问题。先做存储平面分离；做不到就错开「写检查点」和「同步梯度」的时间窗。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Rail-optimized：同号 GPU 对齐到同一上行平面，服务 DP 类同步集体。</li><li>TP 留在 NVLink 域；DP 沿轨展开；EP All-to-All 与轨假设冲突。</li><li>绑定错误等于没有轨优化；要用错绑对照验收。</li><li>轨是调度输入，多租户共享同一轨会毁掉 \\(\\beta\\) 模型。</li><li>出处：DGX SuperPOD 一类 rail-optimized 参考架构；Clos 见上一拓扑课。</li></ul>',9))])}const b=n(d,[["render",P]]);export{h as __pageData,b as default};
